insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('comparando-distintas-estrategias-para-preparar-un-examen','educacion',array[]::text[],'Comparando distintas estrategias para preparar un examen','Compara estrategias de preparación, como resolver exámenes anteriores, hacer resúmenes, estudiar en grupo o repasar con preguntas, y evalúa cuál te dio mejor resultado y menos estrés.','Investigación','4 semanas',24,array['Exámenes','Estrategias']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social autoobservacion. planificacion. analisis de datos. mejora continua. hoja de calculo. un cuaderno de registro. un calendario.',$a14sld${"id": "comparando-distintas-estrategias-para-preparar-un-examen", "area": "educacion", "areas2": [], "titulo": "Comparando distintas estrategias para preparar un examen", "resumen": "Compara estrategias de preparación, como resolver exámenes anteriores, hacer resúmenes, estudiar en grupo o repasar con preguntas, y evalúa cuál te dio mejor resultado y menos estrés.", "tipo": "Investigación", "tiempo": "4 semanas", "horas": 24, "etiquetas": ["Exámenes", "Estrategias"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Antes de un examen la mayoría repite lo que siempre hace, sin saber si realmente es lo que mejor le funciona. Tampoco se acostumbra a evaluar después qué estrategia ayudó y cuál fue pérdida de tiempo.", "Un registro de lo que hiciste y de cómo te fue permite mejorar el siguiente examen."], "desarrollar": ["En dos o tres exámenes del ciclo, registra qué estrategias usaste, cuántas horas dedicaste a cada una y cómo te sentiste. Después del examen anota tu nota y qué tipo de preguntas te resultaron fáciles o difíciles.", "Compara los exámenes, identifica qué estrategias parecen ayudar más y diseña un plan para el siguiente examen. Después del siguiente, evalúa si el plan funcionó."], "ampliaciones": [{"titulo": "Con compañeros", "aporta": "compara tus estrategias con las de dos compañeros."}, {"titulo": "Plan por días", "aporta": "diseña un plan para los siete días previos."}, {"titulo": "Nivel de estrés", "aporta": "agrega un registro de estrés y compara por estrategia."}], "objetivos": ["Registrar estrategias de preparación.", "Relacionarlas con resultados.", "Diseñar un plan.", "Evaluar si funcionó."], "habilidades": ["Autoobservación.", "Planificación.", "Análisis de datos.", "Mejora continua."], "herramientas": ["Hoja de cálculo.", "Un cuaderno de registro.", "Un calendario."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Los resultados de un examen dependen de muchos factores: evita sacar conclusiones fuertes con pocos datos."], "otroSector": "El mismo método sirve para preparar certificaciones, entrevistas o presentaciones importantes."}$a14sld$::jsonb,21),
('cuanto-tiempo-necesito-para-aprender-un-tema-nuevo-y-que-tan-pre','educacion',array['industria']::text[],'¿Cuánto tiempo necesito para aprender un tema nuevo y qué tan precisas son mis estimaciones?','Compara el tiempo que crees que te tomará estudiar cada tema con el que realmente te toma, y aprende a estimar mejor para planificar un ciclo sin sorpresas.','Investigación','3 a 4 semanas',22,array['Estimación del tiempo','Planificación']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social estimacion. registro de datos. calculo simple. planificacion. hoja de calculo. un cronometro. un cuaderno de registro.',$a15sld${"id": "cuanto-tiempo-necesito-para-aprender-un-tema-nuevo-y-que-tan-pre", "area": "educacion", "areas2": ["industria"], "titulo": "¿Cuánto tiempo necesito para aprender un tema nuevo y qué tan precisas son mis estimaciones?", "resumen": "Compara el tiempo que crees que te tomará estudiar cada tema con el que realmente te toma, y aprende a estimar mejor para planificar un ciclo sin sorpresas.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 22, "etiquetas": ["Estimación del tiempo", "Planificación"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Casi todos subestimamos cuánto tarda estudiar un tema nuevo, y por eso los planes se desbordan. El error de estimación se repite ciclo tras ciclo, porque nadie guarda el dato real.", "Medir la diferencia entre lo estimado y lo real permite corregir y planificar con más realismo."], "desarrollar": ["Durante tres a cuatro semanas, antes de estudiar cada tema anota cuánto crees que tardarás, y después registra el tiempo real. Anota también la dificultad percibida y si ya conocías algo del tema.", "Calcula el error medio de tus estimaciones, identifica en qué temas te equivocas más y define un factor de corrección personal para tus planes futuros."], "ampliaciones": [{"titulo": "Por tipo de tarea", "aporta": "compara errores en lectura, problemas y trabajos escritos."}, {"titulo": "Margen de seguridad", "aporta": "calcula cuánto margen debes añadir a tus planes."}, {"titulo": "Con compañeros", "aporta": "compara con otras personas para ver patrones comunes."}], "objetivos": ["Registrar estimaciones y tiempos reales.", "Calcular el error.", "Definir un factor de corrección.", "Planificar con más realismo."], "habilidades": ["Estimación.", "Registro de datos.", "Cálculo simple.", "Planificación."], "herramientas": ["Hoja de cálculo.", "Un cronómetro.", "Un cuaderno de registro."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar."], "otroSector": "El mismo método sirve para mejorar estimaciones de tiempo en proyectos de software o de obras."}$a15sld$::jsonb,22),
('analizando-como-influye-el-lugar-de-estudio-en-la-concentracion','educacion',array['industria']::text[],'Analizando cómo influye el lugar de estudio en la concentración y diseñando un espacio más efectivo','Compara tu rendimiento en distintos lugares de estudio y, con lo observado, rediseña tu espacio para reducir distracciones y mejorar tu concentración.','Investigación','3 a 4 semanas',24,array['Espacio de estudio','Concentración']::text[],array['investigar','crear']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social observacion. registro de datos. diseno de espacios. evaluacion de cambios. hoja de calculo. una aplicacion de medicion de ruido y luz. cuaderno de registro.',$a16sld${"id": "analizando-como-influye-el-lugar-de-estudio-en-la-concentracion", "area": "educacion", "areas2": ["industria"], "titulo": "Analizando cómo influye el lugar de estudio en la concentración y diseñando un espacio más efectivo", "resumen": "Compara tu rendimiento en distintos lugares de estudio y, con lo observado, rediseña tu espacio para reducir distracciones y mejorar tu concentración.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Espacio de estudio", "Concentración"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Se estudia en el cuarto, la biblioteca, la sala o una cafetería, pero casi nunca se compara dónde se rinde más. Pequeños detalles, como el ruido, la iluminación o tener el celular a mano, cambian bastante la concentración.", "Medirlo y ajustar el espacio es un cambio barato que puede mejorar cada sesión."], "desarrollar": ["Durante tres semanas estudia en dos o tres lugares distintos y registra en cada sesión tu concentración, tus distracciones y cuánto avanzaste. Anota condiciones como ruido, luz y temperatura aproximada.", "Compara los lugares, identifica qué condiciones se asocian con mejor rendimiento y rediseña tu espacio con cambios concretos. Prueba el nuevo espacio durante dos semanas y evalúa si mejoró."], "ampliaciones": [{"titulo": "Presupuesto", "aporta": "estima el costo de los cambios y prioriza los más baratos."}, {"titulo": "Orden del escritorio", "aporta": "prueba distintas formas de ordenar y mide el efecto."}, {"titulo": "Espacio compartido", "aporta": "adapta el diseño para quien comparte cuarto."}], "objetivos": ["Comparar lugares de estudio.", "Relacionar condiciones con la concentración.", "Rediseñar el espacio.", "Evaluar el cambio."], "habilidades": ["Observación.", "Registro de datos.", "Diseño de espacios.", "Evaluación de cambios."], "herramientas": ["Hoja de cálculo.", "Una aplicación de medición de ruido y luz.", "Cuaderno de registro."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Este proyecto no da consejos médicos: si tienes molestias en la vista o la espalda, consulta a un profesional.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar."], "otroSector": "El mismo análisis sirve para evaluar espacios de trabajo remoto, aulas o salas de estudio."}$a16sld$::jsonb,23),
('que-distracciones-afectan-mas-mi-aprendizaje','educacion',array['tecnologia']::text[],'¿Qué distracciones afectan más mi aprendizaje?','Registra y clasifica durante dos semanas las distracciones que te sacan de estudiar, cuánto tiempo te quitan y cuáles son las más fáciles de reducir.','Investigación','2 a 3 semanas',18,array['Distracciones','Hábitos']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social autoobservacion. registro de datos. analisis simple. cambio de habitos. hoja de calculo. un cuaderno de registro. las estadisticas de uso del celular.',$a17sld${"id": "que-distracciones-afectan-mas-mi-aprendizaje", "area": "educacion", "areas2": ["tecnologia"], "titulo": "¿Qué distracciones afectan más mi aprendizaje?", "resumen": "Registra y clasifica durante dos semanas las distracciones que te sacan de estudiar, cuánto tiempo te quitan y cuáles son las más fáciles de reducir.", "tipo": "Investigación", "tiempo": "2 a 3 semanas", "horas": 18, "etiquetas": ["Distracciones", "Hábitos"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Casi nadie sabe cuántas veces se distrae al estudiar ni qué lo distrae más. Se culpa al celular, pero a veces pesan más el hambre, el ruido o pensamientos sobre otras tareas.", "Si no se registran, es difícil saber qué cambiar primero."], "desarrollar": ["Durante dos semanas anota cada vez que te distraes al estudiar: qué fue, cuánto duró y qué estabas haciendo. Clasifica las distracciones en externas, como ruido y mensajes, e internas, como preocupaciones.", "Calcula el tiempo perdido por tipo, elige las dos distracciones más costosas y prueba una medida concreta para cada una durante una semana. Compara antes y después."], "ampliaciones": [{"titulo": "Celular", "aporta": "mide específicamente el tiempo en el celular durante el estudio."}, {"titulo": "Distracciones internas", "aporta": "prueba escribir los pensamientos pendientes y seguir estudiando."}, {"titulo": "Meta personal", "aporta": "define una meta realista de reducción."}], "objetivos": ["Registrar distracciones.", "Clasificarlas.", "Medir su costo.", "Probar medidas de reducción."], "habilidades": ["Autoobservación.", "Registro de datos.", "Análisis simple.", "Cambio de hábitos."], "herramientas": ["Hoja de cálculo.", "Un cuaderno de registro.", "Las estadísticas de uso del celular."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Registra solo tu propio uso: no recojas datos de otras personas."], "otroSector": "El mismo registro sirve para analizar distracciones en el trabajo remoto o en una oficina."}$a17sld$::jsonb,24),
('evaluando-la-calidad-de-mis-habitos-de-estudio-actuales','educacion',array[]::text[],'Evaluando la calidad de mis hábitos de estudio actuales','Haz un diagnóstico honesto de tus hábitos de estudio, como horarios, constancia, repaso y entorno, y elige uno o dos para mejorar con un plan realista.','Análisis','2 semanas',16,array['Hábitos','Autoevaluación']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social autoevaluacion. registro de datos. planificacion. mejora continua. hoja de calculo. un calendario. un cuaderno de registro.',$a18sld${"id": "evaluando-la-calidad-de-mis-habitos-de-estudio-actuales", "area": "educacion", "areas2": [], "titulo": "Evaluando la calidad de mis hábitos de estudio actuales", "resumen": "Haz un diagnóstico honesto de tus hábitos de estudio, como horarios, constancia, repaso y entorno, y elige uno o dos para mejorar con un plan realista.", "tipo": "Análisis", "tiempo": "2 semanas", "horas": 16, "etiquetas": ["Hábitos", "Autoevaluación"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Muchos estudiantes creen que estudian bien o mal sin haberlo medido. Un diagnóstico ordenado de los hábitos permite ver qué funciona, qué se hace por costumbre y qué conviene cambiar.", "Sin ese punto de partida, los propósitos de cambiar de método suelen durar pocos días."], "desarrollar": ["Define seis a ocho hábitos que puedas observar, por ejemplo horario regular, repaso semanal, uso del celular y descanso entre sesiones. Durante dos semanas registra cuántos días cumples cada uno.", "Califica cada hábito con una escala simple, elige uno o dos de menor desempeño y diseña un plan pequeño para mejorarlos durante una semana. Evalúa el avance y ajusta."], "ampliaciones": [{"titulo": "Con alguien de confianza", "aporta": "pide a una persona de confianza que observe y compare."}, {"titulo": "Hábitos de arranque", "aporta": "analiza qué te ayuda a empezar a estudiar."}, {"titulo": "Tablero de seguimiento", "aporta": "arma un tablero simple para ver tu avance."}], "objetivos": ["Diagnosticar hábitos de estudio.", "Medir su cumplimiento.", "Elegir hábitos a mejorar.", "Evaluar el avance."], "habilidades": ["Autoevaluación.", "Registro de datos.", "Planificación.", "Mejora continua."], "herramientas": ["Hoja de cálculo.", "Un calendario.", "Un cuaderno de registro."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Evalúa hábitos, no personas: la meta es mejorar, no juzgarte."], "otroSector": "La misma evaluación sirve para hábitos de trabajo, de ejercicio o de alimentación en un equipo."}$a18sld$::jsonb,25),
('un-metodo-para-organizar-el-estudio-de-varias-asignaturas-y-sost','educacion',array['industria']::text[],'Un método para organizar el estudio de varias asignaturas y sostener una rutina durante todo un ciclo','Diseña un método para repartir el estudio de varios cursos durante el ciclo y mantener una rutina sostenible, con semanas de revisión para ajustar según lo que ocurre de verdad.','Plan','4 a 5 semanas',26,array['Planificación','Rutina de estudio']::text[],array['crear','resolver']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social planificacion. autodisciplina. analisis de datos. diseno de guias. hoja de calculo o calendario. un cuaderno de registro. un editor de documentos.',$a19sld${"id": "un-metodo-para-organizar-el-estudio-de-varias-asignaturas-y-sost", "area": "educacion", "areas2": ["industria"], "titulo": "Un método para organizar el estudio de varias asignaturas y sostener una rutina durante todo un ciclo", "resumen": "Diseña un método para repartir el estudio de varios cursos durante el ciclo y mantener una rutina sostenible, con semanas de revisión para ajustar según lo que ocurre de verdad.", "tipo": "Plan", "tiempo": "4 a 5 semanas", "horas": 26, "etiquetas": ["Planificación", "Rutina de estudio"], "intencion": ["crear", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Al inicio del ciclo muchos arman planes ambiciosos que se abandonan a la tercera semana, cuando llegan trabajos, exámenes y cansancio. Una rutina que no soporta imprevistos no sirve.", "Un método realista, con márgenes y revisión periódica, hace más probable sostener el estudio todo el ciclo."], "desarrollar": ["Reúne las fechas del ciclo, tu carga de cursos y tus tiempos fijos. Diseña una semana tipo con bloques por curso, tiempos de repaso y espacios libres para imprevistos, y define reglas simples: qué hacer si falta una sesión o si se junta una entrega.", "Aplícalo durante tres a cuatro semanas, revisa cada domingo qué se cumplió y por qué no, y ajusta. Resume el método en una guía de una página que otro estudiante pueda copiar."], "ampliaciones": [{"titulo": "Semanas de exámenes", "aporta": "diseña una versión intensiva para épocas de evaluaciones."}, {"titulo": "Aprender de los fallos", "aporta": "registra por qué no se cumplen las sesiones y ajusta."}, {"titulo": "Versión para el trabajo", "aporta": "adapta el método a quien estudia y trabaja a la vez."}], "objetivos": ["Diseñar una semana tipo.", "Definir reglas para imprevistos.", "Aplicar y ajustar el método.", "Resumirlo en una guía."], "habilidades": ["Planificación.", "Autodisciplina.", "Análisis de datos.", "Diseño de guías."], "herramientas": ["Hoja de cálculo o calendario.", "Un cuaderno de registro.", "Un editor de documentos."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Haz el método flexible: con márgenes, no con horarios al minuto."], "otroSector": "El mismo método sirve para planificar proyectos de varios frentes en un trabajo o un emprendimiento."}$a19sld$::jsonb,26),
('disenando-un-plan-para-evitar-la-acumulacion-de-tareas-academica','educacion',array[]::text[],'Diseñando un plan para evitar la acumulación de tareas académicas','Descubre por qué se acumulan tus tareas y diseña un plan con revisión semanal, pasos pequeños y fechas intermedias para que las entregas no se junten.','Plan','3 semanas',20,array['Procrastinación','Tareas']::text[],array['crear','resolver']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social gestion del tiempo. registro de datos. planificacion. mejora continua. hoja de calculo o agenda. un cuaderno de registro. un calendario.',$a20sld${"id": "disenando-un-plan-para-evitar-la-acumulacion-de-tareas-academica", "area": "educacion", "areas2": [], "titulo": "Diseñando un plan para evitar la acumulación de tareas académicas", "resumen": "Descubre por qué se acumulan tus tareas y diseña un plan con revisión semanal, pasos pequeños y fechas intermedias para que las entregas no se junten.", "tipo": "Plan", "tiempo": "3 semanas", "horas": 20, "etiquetas": ["Procrastinación", "Tareas"], "intencion": ["crear", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Las tareas rara vez se acumulan de golpe: se van dejando hasta que coinciden varias fechas. Se vuelve un ciclo de prisa, cansancio y trabajos de menor calidad.", "Identificar dónde empieza la acumulación permite cortar el ciclo antes."], "desarrollar": ["Durante dos semanas registra tus tareas con fecha de entrega, cuándo las empezaste y cuándo las terminaste. Identifica en qué momentos empiezas a atrasarte y qué tipo de tareas dejas para el final.", "Diseña un plan con fechas intermedias, división de tareas grandes en pasos pequeños y una revisión semanal de 15 minutos. Pruébalo durante una semana y compara la acumulación antes y después."], "ampliaciones": [{"titulo": "Tareas en grupo", "aporta": "adapta el plan para trabajos en equipo."}, {"titulo": "Alertas tempranas", "aporta": "define señales para detectar cuándo un atraso se vuelve crítico."}, {"titulo": "Recompensas", "aporta": "prueba pequeñas metas y premios y mide si ayudan."}], "objetivos": ["Registrar entregas y atrasos.", "Detectar el origen de la acumulación.", "Diseñar un plan con revisión.", "Evaluar su efecto."], "habilidades": ["Gestión del tiempo.", "Registro de datos.", "Planificación.", "Mejora continua."], "herramientas": ["Hoja de cálculo o agenda.", "Un cuaderno de registro.", "Un calendario."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Evita culparte: usa los datos para entender el patrón."], "otroSector": "El mismo plan sirve para equipos que acumulan tareas pendientes en un proyecto."}$a20sld$::jsonb,27),
('que-actividades-consumen-mas-tiempo-durante-una-semana-academica','educacion',array[]::text[],'¿Qué actividades consumen más tiempo durante una semana académica?','Registra en qué usas realmente las horas de una semana académica, desde clases y traslados hasta redes y descanso, y compara lo que crees que haces con lo que registras.','Análisis','2 a 3 semanas',18,array['Uso del tiempo','Registro']::text[],array['investigar']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social registro de datos. calculo de proporciones. graficos. autoobservacion. hoja de calculo. un cuaderno de registro. un editor de graficos.',$a21sld${"id": "que-actividades-consumen-mas-tiempo-durante-una-semana-academica", "area": "educacion", "areas2": [], "titulo": "¿Qué actividades consumen más tiempo durante una semana académica?", "resumen": "Registra en qué usas realmente las horas de una semana académica, desde clases y traslados hasta redes y descanso, y compara lo que crees que haces con lo que registras.", "tipo": "Análisis", "tiempo": "2 a 3 semanas", "horas": 18, "etiquetas": ["Uso del tiempo", "Registro"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Casi todos tenemos una idea vaga de cómo usamos el tiempo, pero cuando se mide aparecen sorpresas: traslados más largos, horas perdidas en el celular o tiempo de estudio menor al imaginado.", "Un registro simple muestra dónde hay tiempo recuperable y dónde la carga es real."], "desarrollar": ["Durante dos semanas registra tus actividades en bloques de 30 minutos, agrupadas en categorías como clases, traslados, estudio, trabajo, comidas, sueño y ocio. Al final de cada semana, suma horas por categoría.", "Compara el resultado con tu estimación inicial, identifica las categorías más sorprendentes y propón dos ajustes concretos. Presenta los resultados en un gráfico de barras."], "ampliaciones": [{"titulo": "Semana de exámenes", "aporta": "compara una semana normal con una de evaluaciones."}, {"titulo": "Tiempo recuperable", "aporta": "calcula cuántas horas podrías liberar con pequeños cambios."}, {"titulo": "Versiones de compañeros", "aporta": "compara patrones anónimos con otros estudiantes."}], "objetivos": ["Registrar el uso del tiempo.", "Comparar estimado y real.", "Identificar tiempo recuperable.", "Proponer ajustes."], "habilidades": ["Registro de datos.", "Cálculo de proporciones.", "Gráficos.", "Autoobservación."], "herramientas": ["Hoja de cálculo.", "Un cuaderno de registro.", "Un editor de gráficos."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "El objetivo es entender, no sentirte culpable por el tiempo de descanso."], "otroSector": "El mismo registro sirve para analizar el uso del tiempo en un trabajo, un emprendimiento o en casa."}$a21sld$::jsonb,28),
('gestion-del-tiempo-para-equilibrar-estudio-trabajo-y-vida-person','educacion',array['salud','negocios']::text[],'Gestión del tiempo para equilibrar estudio, trabajo y vida personal','Diseña un plan realista para quien debe repartir el tiempo entre estudios, trabajo y vida personal, con prioridades, límites y espacios de descanso que se puedan sostener.','Plan','3 a 4 semanas',22,array['Equilibrio','Estudiar y trabajar']::text[],array['crear','resolver']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social gestion del tiempo. priorizacion. comunicacion. autocuidado en la planificacion. hoja de calculo o calendario. un cuaderno de registro. un editor de documentos.',$a22sld${"id": "gestion-del-tiempo-para-equilibrar-estudio-trabajo-y-vida-person", "area": "educacion", "areas2": ["salud", "negocios"], "titulo": "Gestión del tiempo para equilibrar estudio, trabajo y vida personal", "resumen": "Diseña un plan realista para quien debe repartir el tiempo entre estudios, trabajo y vida personal, con prioridades, límites y espacios de descanso que se puedan sostener.", "tipo": "Plan", "tiempo": "3 a 4 semanas", "horas": 22, "etiquetas": ["Equilibrio", "Estudiar y trabajar"], "intencion": ["crear", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Estudiar y trabajar, o atender responsabilidades en casa, deja poco margen. Muchos cargan con todo y terminan agotados, bajando el rendimiento en ambos frentes.", "Un plan que parta de las horas reales disponibles y de lo que no se puede mover ayuda a decidir con más calma."], "desarrollar": ["Mapea tu semana con los bloques fijos, como clases, trabajo y traslados, y las horas libres reales. Identifica qué tareas son urgentes e importantes y cuáles se pueden reducir, delegar o postergar.", "Diseña un plan semanal con prioridades, límites y descansos, pruébalo durante tres semanas y ajusta cada semana con una revisión corta. Resume tus reglas en una guía breve."], "ampliaciones": [{"titulo": "Semana difícil", "aporta": "diseña un plan de emergencia para semanas con muchas cargas."}, {"titulo": "Hablar con docentes y jefes", "aporta": "prepara cómo pedir flexibilidad con argumentos claros."}, {"titulo": "Indicadores", "aporta": "define señales de sobrecarga para actuar a tiempo."}], "objetivos": ["Mapear la semana real.", "Definir prioridades y límites.", "Probar un plan.", "Resumir reglas."], "habilidades": ["Gestión del tiempo.", "Priorización.", "Comunicación.", "Autocuidado en la planificación."], "herramientas": ["Hoja de cálculo o calendario.", "Un cuaderno de registro.", "Un editor de documentos."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Este proyecto no es un consejo de salud: si sientes agotamiento o ansiedad constantes, busca apoyo profesional o en tu centro de estudios.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar."], "otroSector": "El mismo plan sirve para personas que cuidan a familiares o emprenden mientras estudian."}$a22sld$::jsonb,29),
('disenando-un-calendario-academico-adaptado-a-mis-necesidades','educacion',array[]::text[],'Diseñando un calendario académico adaptado a mis necesidades','Construye un calendario del ciclo que reúna clases, entregas, exámenes y tiempos de repaso, con colores, alertas y revisiones que se adapten a tu forma de organizarte.','Plan','2 a 3 semanas',18,array['Calendario','Organización']::text[],array['crear']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social organizacion. planificacion. uso de herramientas digitales. mejora continua. un calendario digital o fisico. hoja de calculo. los silabos de tus cursos.',$a23sld${"id": "disenando-un-calendario-academico-adaptado-a-mis-necesidades", "area": "educacion", "areas2": [], "titulo": "Diseñando un calendario académico adaptado a mis necesidades", "resumen": "Construye un calendario del ciclo que reúna clases, entregas, exámenes y tiempos de repaso, con colores, alertas y revisiones que se adapten a tu forma de organizarte.", "tipo": "Plan", "tiempo": "2 a 3 semanas", "horas": 18, "etiquetas": ["Calendario", "Organización"], "intencion": ["crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Hay estudiantes que usan una agenda de papel, otros el celular y otros nada, y a veces se les pasan fechas importantes. Un calendario sirve solo si se mira y se actualiza.", "Adaptarlo a cómo trabajas tú aumenta las posibilidades de usarlo todo el ciclo."], "desarrollar": ["Reúne las fechas del ciclo, de sílabos, exámenes y trabajos, y compara dos herramientas de calendario, una física y una digital, durante una semana para ver con cuál te organizas mejor.", "Diseña tu calendario con un código de colores, alertas anticipadas y una revisión semanal. Úsalo durante tres semanas y evalúa qué cambiarías."], "ampliaciones": [{"titulo": "Versión compartida", "aporta": "arma un calendario común para un grupo de estudio."}, {"titulo": "Fechas críticas", "aporta": "define alertas especiales para semanas con muchas entregas."}, {"titulo": "Revisión de fin de ciclo", "aporta": "evalúa al final del ciclo qué funcionó."}], "objetivos": ["Reunir las fechas del ciclo.", "Comparar herramientas de calendario.", "Diseñar un calendario propio.", "Evaluar su uso."], "habilidades": ["Organización.", "Planificación.", "Uso de herramientas digitales.", "Mejora continua."], "herramientas": ["Un calendario digital o físico.", "Hoja de cálculo.", "Los sílabos de tus cursos."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Usa herramientas que ya existan y cuyas condiciones de uso respetes; no subas datos de otras personas a plataformas sin su permiso.", "Mantén el calendario sencillo: demasiados colores y alertas lo vuelven inútil."], "otroSector": "El mismo diseño sirve para organizar proyectos de trabajo o eventos."}$a23sld$::jsonb,30),
('evaluando-el-uso-de-listas-de-tareas-en-el-seguimiento-del-apren','educacion',array[]::text[],'Evaluando el uso de listas de tareas en el seguimiento del aprendizaje','Prueba distintas formas de listas de tareas, como una lista diaria, una semanal o un tablero por estados, y evalúa cuál te ayuda a cumplir más y a no olvidar pendientes.','Investigación','3 semanas',18,array['Listas de tareas','Seguimiento']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social priorizacion. autoobservacion. registro de datos. comparacion. papel o una herramienta de listas. hoja de calculo. cuaderno de registro.',$a24sld${"id": "evaluando-el-uso-de-listas-de-tareas-en-el-seguimiento-del-apren", "area": "educacion", "areas2": [], "titulo": "Evaluando el uso de listas de tareas en el seguimiento del aprendizaje", "resumen": "Prueba distintas formas de listas de tareas, como una lista diaria, una semanal o un tablero por estados, y evalúa cuál te ayuda a cumplir más y a no olvidar pendientes.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 18, "etiquetas": ["Listas de tareas", "Seguimiento"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Las listas de tareas son un recurso muy usado, pero a veces se vuelven una lista enorme que da más ansiedad que claridad. No es lo mismo anotar todo que decidir qué hacer hoy.", "Comparar formatos muestra cuál se adapta mejor a tu estilo."], "desarrollar": ["Durante tres semanas usa una forma distinta de lista cada semana: una lista diaria con tres prioridades, una lista semanal y un tablero con por hacer, en curso y hecho. Registra cuántas tareas planificadas cumpliste cada día.", "Compara cumplimiento, sensación de control y tiempo que te toma mantener cada lista, y elige la que mejor te sirve. Anota ajustes."], "ampliaciones": [{"titulo": "Tareas pequeñas", "aporta": "prueba dividir tareas grandes y mide el efecto."}, {"titulo": "Papel o digital", "aporta": "compara listas en papel con las digitales."}, {"titulo": "Revisión nocturna", "aporta": "evalúa si preparar la lista del día siguiente ayuda."}], "objetivos": ["Comparar formatos de lista.", "Medir cumplimiento.", "Elegir el formato adecuado.", "Documentar la experiencia."], "habilidades": ["Priorización.", "Autoobservación.", "Registro de datos.", "Comparación."], "herramientas": ["Papel o una herramienta de listas.", "Hoja de cálculo.", "Cuaderno de registro."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Usa herramientas que ya existan y cuyas condiciones de uso respetes; no subas datos de otras personas a plataformas sin su permiso.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión."], "otroSector": "La misma comparación sirve para elegir cómo hacer seguimiento de tareas en un equipo."}$a24sld$::jsonb,31),
('disenando-una-estrategia-para-cumplir-objetivos-de-aprendizaje-a','educacion',array[]::text[],'Diseñando una estrategia para cumplir objetivos de aprendizaje a largo plazo','Elige un objetivo de aprendizaje de varios meses, como un idioma o una certificación, y diseña una estrategia con hitos, indicadores y revisiones para no abandonarlo a mitad de camino.','Plan','4 a 6 semanas',22,array['Objetivos','Largo plazo']::text[],array['crear','resolver']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social planificacion. autodisciplina. seguimiento de indicadores. mejora continua. hoja de calculo. un calendario. un cuaderno de registro.',$a25sld${"id": "disenando-una-estrategia-para-cumplir-objetivos-de-aprendizaje-a", "area": "educacion", "areas2": [], "titulo": "Diseñando una estrategia para cumplir objetivos de aprendizaje a largo plazo", "resumen": "Elige un objetivo de aprendizaje de varios meses, como un idioma o una certificación, y diseña una estrategia con hitos, indicadores y revisiones para no abandonarlo a mitad de camino.", "tipo": "Plan", "tiempo": "4 a 6 semanas", "horas": 22, "etiquetas": ["Objetivos", "Largo plazo"], "intencion": ["crear", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Los objetivos grandes, como aprender un idioma, programar o rendir una certificación, se abandonan porque no se dividen en pasos y porque la motivación inicial se acaba. Sin hitos ni revisión, no se sabe si se avanza.", "Una estrategia con metas intermedias y ajustes periódicos hace posible sostener el esfuerzo."], "desarrollar": ["Define un objetivo concreto con fecha, conviértelo en hitos mensuales y semanales y escoge indicadores simples de avance, como horas practicadas o ejercicios resueltos. Anticipa los obstáculos más probables.", "Aplica la estrategia durante cuatro a seis semanas, haz una revisión semanal de 15 minutos y ajusta los hitos. Resume qué funcionó y qué cambiarías."], "ampliaciones": [{"titulo": "Compañero de metas", "aporta": "compara avances con una persona que persiga un objetivo similar."}, {"titulo": "Plan de recaída", "aporta": "define qué hacer si dejas de practicar una semana."}, {"titulo": "Visualización", "aporta": "diseña un gráfico simple de avance."}], "objetivos": ["Definir un objetivo concreto.", "Dividirlo en hitos.", "Hacer seguimiento.", "Ajustar la estrategia."], "habilidades": ["Planificación.", "Autodisciplina.", "Seguimiento de indicadores.", "Mejora continua."], "herramientas": ["Hoja de cálculo.", "Un calendario.", "Un cuaderno de registro."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Elige objetivos realistas: es mejor cumplir uno pequeño que abandonar uno grande."], "otroSector": "La misma estrategia sirve para metas profesionales o de salud de largo plazo."}$a25sld$::jsonb,32),
('comparando-distintas-formas-de-organizar-materiales-de-estudio','educacion',array['tecnologia']::text[],'Comparando distintas formas de organizar materiales de estudio','Compara maneras de organizar archivos, apuntes y lecturas, como carpetas por curso, por semana o por tipo de material, y mide cuánto tardas en encontrar lo que necesitas.','Análisis','2 a 3 semanas',18,array['Organización','Materiales']::text[],array['investigar','resolver']::text[],'propios',NULL,'educacion ingenieria de sistemas ciencia de datos psicologia comunicaciones estadistica diseno administracion organizacion de informacion. medicion. comparacion. gestion de archivos. un explorador de archivos. hoja de calculo. un cronometro.',$a26sld${"id": "comparando-distintas-formas-de-organizar-materiales-de-estudio", "area": "educacion", "areas2": ["tecnologia"], "titulo": "Comparando distintas formas de organizar materiales de estudio", "resumen": "Compara maneras de organizar archivos, apuntes y lecturas, como carpetas por curso, por semana o por tipo de material, y mide cuánto tardas en encontrar lo que necesitas.", "tipo": "Análisis", "tiempo": "2 a 3 semanas", "horas": 18, "etiquetas": ["Organización", "Materiales"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Ingeniería de Sistemas", "Ciencia de Datos", "Psicología", "Comunicaciones", "Estadística", "Diseño", "Administración"], "problema": ["Con el tiempo los materiales de estudio se acumulan: PDFs, fotos de pizarra, capturas y apuntes. Si no están ordenados, se pierde tiempo buscando o se estudia con versiones incompletas.", "Probar distintas formas de organización con tareas de búsqueda reales muestra cuál funciona mejor."], "desarrollar": ["Reúne los materiales de dos cursos y organízalos de dos maneras diferentes, por ejemplo por curso y semana, y por tipo de material. Define cinco tareas de búsqueda, como encontrar la diapositiva de un tema, y mide cuánto tardas en cada forma.", "Compara tiempos y errores, elige el sistema más simple de mantener y escribe reglas de nombres de archivo y de carpetas que puedas aplicar siempre."], "ampliaciones": [{"titulo": "Nombres de archivos", "aporta": "prueba una convención de nombres y mide su efecto."}, {"titulo": "Copias de respaldo", "aporta": "añade un plan simple de copias de seguridad."}, {"titulo": "Organización compartida", "aporta": "diseña una estructura común para un grupo de estudio."}], "objetivos": ["Comparar formas de organizar.", "Medir tiempos de búsqueda.", "Definir reglas de orden.", "Aplicarlas a un ciclo."], "habilidades": ["Organización de información.", "Medición.", "Comparación.", "Gestión de archivos."], "herramientas": ["Un explorador de archivos.", "Hoja de cálculo.", "Un cronómetro."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Usa herramientas que ya existan y cuyas condiciones de uso respetes; no subas datos de otras personas a plataformas sin su permiso.", "No subas materiales con derechos de autor ajenos a plataformas públicas."], "otroSector": "El mismo análisis sirve para organizar documentos de un proyecto o archivos de una oficina."}$a26sld$::jsonb,33)
